mapper.sql:
        where 1=1
        
            and mn.Sll_Login_Type like concat('%',#{params.sllLoginType},'%')
        
        
            and mn.sll_action=#{params.sllAction}
        
        
            and INSTR(mn.Sll_Ip,#{params.sllIp})
        
        
            and INSTR(u.U_Name,#{params.uName})
        
        
            and INSTR(u.U_Account,#{params.uAccount})
        

        
            and mn.Sll_Login_Time>#{params.sllLoginTimeStart}
        
        
            and mn.Sll_Login_Time<#{params.sllLoginTimeEnd}

mapper.select:
select
u.U_Name as uName,
u.U_Account as uAccount,
mn.*
from Sys_Login_Log mn
left join SYS_User u on u.U_Id=mn.U_Id


    
        order by mn.${params.sortFiled} ${params.sortType}
    
    
        order by ${params.sortSideFiled} ${params.sortType}
    
    
        order by mn.Sll_Login_Time desc
    

limit #{params.start},#{params.size}
